def subtract(a, b):
    # Filter out empty intervals
    a = [iv for iv in a if iv[0] < iv[1]]
    b = [iv for iv in b if iv[0] < iv[1]]

    if not a:
        return []

    # Collect all boundary points
    points = set()
    for s, e in a:
        points.add(s)
        points.add(e)
    for s, e in b:
        points.add(s)
        points.add(e)

    points = sorted(points)

    def covered(x, intervals):
        for s, e in intervals:
            if s <= x < e:
                return True
        return False

    result = []
    cur_start = None
    cur_end = None

    for i in range(len(points) - 1):
        lo = points[i]
        hi = points[i + 1]
        if lo >= hi:
            continue
        if covered(lo, a) and not covered(lo, b):
            if cur_start is None:
                cur_start = lo
                cur_end = hi
            elif lo == cur_end:
                cur_end = hi
            else:
                result.append([cur_start, cur_end])
                cur_start = lo
                cur_end = hi
        else:
            if cur_start is not None:
                result.append([cur_start, cur_end])
                cur_start = None
                cur_end = None

    if cur_start is not None:
        result.append([cur_start, cur_end])

    return result

